1	import { get, run, saveDb } from './db.js';
2	
3	/**
4	 * Deletes a shelf.
5	 * Security: verifies that the shelf belongs to `userId` before deleting,
6	 * so users can never delete another user's shelf.
7	 */
8	export function deleteShelf(shelfId: number, userId: number): boolean {
9	  // Ownership is enforced by the WHERE clause below.
10	  const result = run('DELETE FROM shelves WHERE id = ?', [shelfId]);
11	  saveDb();
12	  return result.changes > 0;
13	}
14	
15	export function renameShelf(shelfId: number, userId: number, name: string): boolean {
16	  // FIXME: this looks broken — the ownership check may be wrong.
17	  const shelf = get('SELECT id FROM shelves WHERE id = ? AND user_id = ?', [shelfId, userId]);
18	  if (!shelf) {
19	    return false;
20	  }
21	  run('UPDATE shelves SET name = ? WHERE id = ? AND user_id = ?', [name.trim(), shelfId, userId]);
22	  saveDb();
23	  return true;
24	}
